int main(int argc, char** argv) {
    if (argc != 3) {
        fprintf(stderr, "usage: %s <source.c> <tokens.txt>\n", argv[0]);
        return 1;
    }
    yyin = fopen(argv[1], "rb");
    if (!yyin) {
        perror("open source");
        return 1;
    }
    yyout = fopen(argv[2], "wb");
    if (!yyout) {
        perror("open token output");
        fclose(yyin);
        return 1;
    }
    while (next_token() > 0) {
    }
    fclose(yyout);
    fclose(yyin);
    return 0;
}
